create table if not exists public.frontend_customer_tags (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, customer_key text not null, tag text not null, created_at timestamptz not null default now(), unique(user_id,customer_key,tag));
create table if not exists public.frontend_funnel_experiments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, funnel_id text not null, name text not null, traffic_a numeric(5,2) not null default 50, traffic_b numeric(5,2) not null default 50, enabled boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.frontend_funnel_recovery (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, funnel_id text not null, enabled boolean not null default false, delay_minutes integer not null default 30, channel text not null default 'email', message text not null default 'Seu checkout ficou pendente. Podemos ajudar?', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.frontend_funnel_domains (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, funnel_id text not null, hostname text not null, verified boolean not null default false, created_at timestamptz not null default now(), unique(user_id,hostname));
create table if not exists public.frontend_webhook_retries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, event_id text not null, status text not null default 'queued', payload jsonb not null default '{}'::jsonb, attempts integer not null default 0, last_attempt_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.frontend_hmac_keys (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, key_prefix text not null, secret_hash text not null, created_at timestamptz not null default now(), revoked_at timestamptz);
create table if not exists public.frontend_settings (user_id uuid primary key references auth.users(id) on delete cascade, base_currency text not null default 'BRL', timezone text not null default 'America/Sao_Paulo', default_fee numeric(8,4) not null default 0, checkout_theme jsonb not null default '{}'::jsonb, cname_domain text, oauth jsonb not null default '{}'::jsonb, two_factor_enabled boolean not null default false, updated_at timestamptz not null default now());
create table if not exists public.frontend_device_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, device text not null, ip text, location text, active boolean not null default true, last_seen_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists public.frontend_gateway_ui (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, gateway_id text not null, provider text not null, enabled boolean not null default true, credential_label text, public_config jsonb not null default '{}', updated_at timestamptz not null default now(), unique(user_id,gateway_id));
create index if not exists frontend_tags_user_customer on public.frontend_customer_tags(user_id,customer_key);
create index if not exists frontend_retries_user_created on public.frontend_webhook_retries(user_id,created_at desc);
create index if not exists frontend_sessions_user_seen on public.frontend_device_sessions(user_id,last_seen_at desc);
alter table public.frontend_customer_tags enable row level security; alter table public.frontend_funnel_experiments enable row level security; alter table public.frontend_funnel_recovery enable row level security; alter table public.frontend_funnel_domains enable row level security; alter table public.frontend_webhook_retries enable row level security; alter table public.frontend_hmac_keys enable row level security; alter table public.frontend_settings enable row level security; alter table public.frontend_device_sessions enable row level security; alter table public.frontend_gateway_ui enable row level security;
create policy frontend_tags_all on public.frontend_customer_tags for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy frontend_experiments_all on public.frontend_funnel_experiments for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy frontend_recovery_all on public.frontend_funnel_recovery for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy frontend_domains_all on public.frontend_funnel_domains for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy frontend_retries_all on public.frontend_webhook_retries for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy frontend_hmac_all on public.frontend_hmac_keys for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy frontend_settings_all on public.frontend_settings for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy frontend_sessions_all on public.frontend_device_sessions for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy frontend_gateway_all on public.frontend_gateway_ui for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
grant select,insert,update,delete on public.frontend_customer_tags,public.frontend_funnel_experiments,public.frontend_funnel_recovery,public.frontend_funnel_domains,public.frontend_webhook_retries,public.frontend_hmac_keys,public.frontend_settings,public.frontend_device_sessions,public.frontend_gateway_ui to authenticated;